'use strict';
const heart='<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z"/></svg>';
const $=id=>document.getElementById(id);
let favorites=new Set();try{const saved=JSON.parse(localStorage.getItem('sole-archive-picks')||'[]');if(Array.isArray(saved)) favorites=new Set(saved.filter(id=>COLLECTION.some(p=>p.id===id)))}catch{}
let selectedBrand='ALL',savedOnly=false,sort='curated',activeProduct=null,toastTimer;
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const brands=['ALL','NIKE/JORDAN','SALOMON','On','HOKA'];
$('filters').innerHTML=brands.map(b=>`<button class="filter" aria-pressed="${b===selectedBrand}" data-brand="${esc(b)}">${esc(b)}</button>`).join('');
function visibleProducts(){let items=COLLECTION.filter(p=>(selectedBrand==='ALL'||p.brand===selectedBrand)&&(!savedOnly||favorites.has(p.id)));if(sort!=='curated')items.sort((a,b)=>(sort==='brand'?a.brand:a.name).localeCompare(sort==='brand'?b.brand:b.name));return items}
function render(){applyBrandTheme(selectedBrand);const items=visibleProducts();$('gallery').dataset.brandFiltered=String(selectedBrand!=='ALL');$('gallery').innerHTML=items.map((p,i)=>`<article class="card ${i===0&&!savedOnly&&selectedBrand==='ALL'&&sort==='curated'?'featured':''}"><button class="favorite" data-favorite="${p.id}" aria-label="${esc(p.name)}をお気に入り${favorites.has(p.id)?'から削除':'に追加'}" aria-pressed="${favorites.has(p.id)}">${heart}</button><button class="card-main" data-detail="${p.id}" aria-label="${esc(p.name)}の詳細を見る"><div class="card-meta"><span class="card-brand">${esc(p.brand)}</span><span class="card-number">NO. ${String(p.number||p.id).padStart(3,'0')}</span></div><div class="image-wrap">${i===0&&!savedOnly&&selectedBrand==='ALL'&&sort==='curated'?'<span class="feature-watermark" aria-hidden="true">ICON</span>':''}<img src="${esc(p.image)}" alt="${esc(p.name+' '+p.color)}" width="900" height="600" ${i>2?'loading="lazy"':'fetchpriority="high"'}></div><div class="card-copy">${i===0&&!savedOnly&&selectedBrand==='ALL'&&sort==='curated'?'<div class="feature-stamp">IN THE SPOTLIGHT</div>':''}<h2>${esc(p.name)}</h2><span class="colorway">${esc(p.color)}</span></div><span class="detail-hint" aria-hidden="true">+</span></button><button class="exhibit-entry" type="button" data-exhibit="${p.id}" aria-label="${esc(p.name)}を展示モードで見る">VIEW IN EXHIBITION <span aria-hidden="true">↗</span></button></article>`).join('');$('empty').hidden=items.length>0;$('saved-count').textContent=favorites.size;$('result-count').textContent=String(items.length).padStart(2,'0')+' PAIRS';$('saved-toggle').setAttribute('aria-pressed',savedOnly);$('saved-notice').hidden=!savedOnly;document.querySelectorAll('.filter').forEach(b=>b.setAttribute('aria-pressed',b.dataset.brand===selectedBrand));}
function toast(message){$('toast').textContent=message;$('toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('visible'),2300)}
function setFavorite(id,wanted){if(!COLLECTION.some(p=>p.id===id))throw new Error('Unknown sneaker');if(wanted)favorites.add(id);else favorites.delete(id);let persisted=true;try{localStorage.setItem('sole-archive-picks',JSON.stringify([...favorites]))}catch{persisted=false}render();if(activeProduct)updateDetailFavorite();toast(persisted?(wanted?'MY PICKS に追加しました':'MY PICKS から外しました'):'この画面内に保存しました。ブラウザへの保存はできませんでした。');return{id,saved:wanted,persisted}}
function toggleFavorite(id){return setFavorite(id,!favorites.has(id))}
function updateDetailFavorite(){const btn=$('detail-favorite');if(btn&&activeProduct){btn.setAttribute('aria-pressed',favorites.has(activeProduct.id));btn.textContent=favorites.has(activeProduct.id)?'MY PICKS に保存済み':'MY PICKS に追加'}}
function openDetail(id){const p=COLLECTION.find(p=>p.id===id);if(!p)throw new Error('Unknown sneaker');activeProduct=p;$('detail-content').innerHTML=`<div class="detail-layout"><div class="detail-art"><img src="${esc(p.image)}" alt="${esc(p.name+' '+p.color)}" width="900" height="600"></div><div class="detail-info"><div class="eyebrow">${esc(p.brand)} / NO. ${String(p.number||p.id).padStart(3,'0')}</div><h2 id="detail-title">${esc(p.name)}</h2><p class="detail-color">${esc(p.color)}</p><p>${esc(p.description)}</p><button class="dark-button" id="detail-favorite"></button><button class="detail-exhibit" id="detail-exhibit" type="button">展示モードで眺める ↗</button><a class="source-link" href="${esc(p.source)}" target="_blank" rel="noopener noreferrer">モデル・写真の出典を見る</a></div></div>`;updateDetailFavorite();$('detail-favorite').onclick=()=>toggleFavorite(id);$('detail-exhibit').onclick=()=>{ $('detail-dialog').close();openExhibition(id) }; if(!$('detail-dialog').open)$('detail-dialog').showModal();syncScrollLock();}
function resetView(){savedOnly=false;selectedBrand='ALL';render()}
$('filters').addEventListener('click',e=>{const b=e.target.closest('[data-brand]');if(b){selectedBrand=b.dataset.brand;render()}});
$('gallery').addEventListener('click',e=>{const f=e.target.closest('[data-favorite]');if(f){toggleFavorite(f.dataset.favorite);return}const x=e.target.closest('[data-exhibit]');if(x){openExhibition(x.dataset.exhibit);return}const d=e.target.closest('[data-detail]');if(d)openDetail(d.dataset.detail)});
$('sort').addEventListener('change',e=>{sort=e.target.value;render()});
$('saved-toggle').onclick=()=>{savedOnly=!savedOnly;selectedBrand='ALL';render();$('collection').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'instant':'smooth'})};
$('reset-view').onclick=resetView;$('empty-reset').onclick=resetView;
$('credits-list').innerHTML=COLLECTION.map(p=>`<li><a href="${esc(p.source)}" target="_blank" rel="noopener noreferrer">${esc(p.brand+' / '+p.name)}</a><br>${esc(p.credit)}${p.licenseUrl?' · <a href="'+esc(p.licenseUrl)+'" target="_blank" rel="noopener noreferrer">ライセンス</a>（表示用に縮小・WebP変換）':''}</li>`).join('');
$('credits-open').onclick=()=>{$('credits-dialog').showModal();document.body.style.overflow='hidden'};
document.querySelectorAll('dialog').forEach(dialog=>{const close=dialog.querySelector('.modal-close');if(close)close.onclick=()=>dialog.close();dialog.addEventListener('close',()=>{syncScrollLock();if(dialog.id==='detail-dialog')activeProduct=null});dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}})});
initializeExhibition();render();
if(document.modelContext?.registerTool){const life=new AbortController();window.addEventListener('pagehide',()=>life.abort(),{once:true});const register=t=>{try{Promise.resolve(document.modelContext.registerTool(t,{signal:life.signal})).catch(()=>{})}catch{}};register({name:'filter_sneaker_collection',description:'Filter the displayed sneaker gallery by brand and optionally show only this browser’s saved picks.',inputSchema:{type:'object',properties:{brand:{type:'string',enum:brands},savedOnly:{type:'boolean'}},required:['brand','savedOnly'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input||!brands.includes(input.brand)||typeof input.savedOnly!=='boolean')throw new Error('Invalid filter');selectedBrand=input.brand;savedOnly=input.savedOnly;render();return{pairs:visibleProducts().map(p=>({id:p.id,brand:p.brand,name:p.name}))}}});register({name:'set_sneaker_favorite',description:'Save or remove a sneaker from MY PICKS on this browser.',inputSchema:{type:'object',properties:{id:{type:'string',enum:COLLECTION.map(p=>p.id)},saved:{type:'boolean'}},required:['id','saved'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input||typeof input.id!=='string'||typeof input.saved!=='boolean')throw new Error('Invalid favorite');return setFavorite(input.id,input.saved)}})}
